<script setup lang="ts">
import { computed, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { management, type RosterCandidate, type RosterRow, type RosterResult } from '../api/management';
import { newClientId } from '../lib/id';
const props=defineProps<{classId:string;className:string}>();
const emit=defineEmits<{close:[];done:[]}>();
const mode=ref('text'),text=ref(''),file=ref<File>(),rows=ref<RosterCandidate[]>([]),warnings=ref<string[]>([]),selected=ref<number[]>([]),password=ref(''),error=ref(''),busy=ref(false),result=ref<RosterResult>();
const checked=ref('');let commitKey='',signature='';
const chosen=computed<RosterRow[]>(()=>rows.value.filter(r=>selected.value.includes(r.rowNumber)).map(({rowNumber,studentNumber,name,username,className})=>({rowNumber,studentNumber,name,username,className})));
const currentSignature=computed(()=>JSON.stringify(chosen.value));
const verified=computed(()=>!!chosen.value.length && checked.value===currentSignature.value && !rows.value.some(r=>selected.value.includes(r.rowNumber)&&r.issues.length));
const names:Record<string,string>={NEW:'新建账号',EXISTING:'加入班级',ALREADY_MEMBER:'已在班级',INVALID:'需修正'};
function sample(){mode.value='text';text.value='学号\t姓名\t班级\n20261001\t张三\t'+props.className+'\n20261002\t李四\t'+props.className;}
function selectFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0];}
async function preview(){busy.value=true;error.value='';try{const input=mode.value==='file'?file.value:text.value;if(!input)throw new Error('请粘贴名单或选择文件');const value=await management.previewRoster(props.classId,input);rows.value=value.rows;warnings.value=value.warnings;selected.value=rows.value.map(r=>r.rowNumber);checked.value=currentSignature.value;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function validate(){busy.value=true;error.value='';try{const value=await management.validateRoster(props.classId,chosen.value);const byLine=new Map(value.rows.map(r=>[r.rowNumber,r]));rows.value=rows.value.map(r=>byLine.get(r.rowNumber)||r);checked.value=currentSignature.value;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function commit(){if(!verified.value)return;busy.value=true;error.value='';try{const next=JSON.stringify([chosen.value,password.value]);if(next!==signature){signature=next;commitKey=newClientId();}result.value=await management.commitRoster(props.classId,chosen.value,password.value,commitKey);password.value='';signature='';ElMessage.success('学生名单已导入');emit('done');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><el-dialog :model-value="true" :title="`导入学生 · ${className}`" width="1040px" :close-on-click-modal="false" :show-close="!busy" @close="emit('close')"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="result"><el-result icon="success" title="导入完成" :sub-title="`新建 ${result.created} 个账号，加入 ${result.added} 人，已在班级 ${result.unchanged} 人`"/></template><template v-else-if="!rows.length"><div class="section-bar"><span class="muted">每次最多 200 人，需包含学号和姓名。</span><el-button link type="primary" @click="sample">填写示例</el-button></div><el-tabs v-model="mode"><el-tab-pane label="粘贴名单" name="text"><el-input v-model="text" type="textarea" :rows="12" placeholder="可直接粘贴 Excel 表格，或填写：&#10;学号 姓名 班级&#10;20261001 张三 计算机1班"/></el-tab-pane><el-tab-pane label="上传文件" name="file"><label class="file-drop"><strong>选择学生名单</strong><span>XLSX / DOCX / CSV / TSV / TXT · 最大 5 MB</span><input type="file" accept=".xlsx,.docx,.csv,.tsv,.txt" @change="selectFile"/><span v-if="file">{{file.name}}</span></label></el-tab-pane></el-tabs></template><template v-else><el-alert v-for="(warning,i) in warnings" :key="i" :title="warning" type="info" :closable="false"/><p class="muted">请核对学号、姓名和登录账号。新账号未指定登录账号时使用学号。</p><div class="roster-table"><el-table :data="rows" max-height="420"><el-table-column width="45"><template #default="{row}"><el-checkbox v-model="selected" :value="row.rowNumber" :aria-label="`选择第 ${row.rowNumber} 行`" :disabled="busy"/></template></el-table-column><el-table-column label="行" prop="rowNumber" width="50"/><el-table-column label="学号" min-width="150"><template #default="{row}"><el-input v-model="row.studentNumber" :disabled="busy"/></template></el-table-column><el-table-column label="姓名" min-width="120"><template #default="{row}"><el-input v-model="row.name" :disabled="busy"/></template></el-table-column><el-table-column label="登录账号" min-width="150"><template #default="{row}"><el-input v-model="row.username" :disabled="busy"/></template></el-table-column><el-table-column label="班级" min-width="150"><template #default="{row}"><el-input v-model="row.className" :placeholder="className" :disabled="busy"/></template></el-table-column><el-table-column label="处理结果" min-width="180"><template #default="{row}"><span :class="row.issues.length?'danger':'success'">{{names[row.action]}}</span><p v-for="issue in row.issues" :key="issue" class="roster-issue">{{issue}}</p></template></el-table-column></el-table></div><div class="roster-footer"><el-form label-position="top"><el-form-item label="新账号初始密码（已有账号密码不变）"><el-input v-model="password" type="password" show-password autocomplete="new-password" placeholder="至少 8 位，包含字母和数字" :disabled="busy"/></el-form-item></el-form><span>已选 {{selected.length}} 人</span><el-button :loading="busy" :disabled="!selected.length" @click="validate">重新校验</el-button></div><p v-if="!verified" class="muted">修改内容或选择范围后，请重新校验。</p></template><template #footer><el-button :disabled="busy" @click="emit('close')">{{result?'完成':'取消'}}</el-button><el-button v-if="!result&&!rows.length" type="primary" :loading="busy" @click="preview">识别名单</el-button><template v-else-if="!result"><el-button :disabled="busy" @click="rows=[];checked=''">重新提供名单</el-button><el-button type="primary" :disabled="!verified||!password" :loading="busy" @click="commit">确认导入</el-button></template></template></el-dialog></template>
<style scoped>.roster-footer{display:flex;align-items:center;gap:15px;margin-top:20px;flex-wrap:wrap}.roster-footer .el-form{flex:1;min-width:220px}.roster-footer .el-form-item{margin:0}.roster-issue{font-size:11px;color:var(--danger-text, #b35b4f);margin:3px 0}.roster-table :deep(.el-table .el-table__cell){padding:8px 0}</style>
